with s1 as (with recursive s2_seed(root_id) as not materialized (select n1.id as root_id from s0, node n1, unnest(array [@__strlit0::text, @__strlit1::text]::text[]) as i0 where ((n1.properties ->> E'objectid') = i0)), s2(root_id, next_id, depth, satisfied, is_cycle, path) as (select e0.end_id, e0.start_id, 1, false, e0.end_id = e0.start_id, array [e0.id] from s2_seed join edge e0 on e0.end_id = s2_seed.root_id where e0.kind_id = any (array [101, 134]::int2[]) union select s2.root_id, e0.start_id, s2.depth + 1, false, false, e0.id || s2.path from s2 join lateral (select e0.id, e0.start_id, e0.end_id, e0.kind_id, e0.properties from edge e0 where e0.end_id = s2.next_id and e0.id != all (s2.path) and e0.kind_id = any (array [101, 134]::int2[]) offset 0) e0 on true where s2.depth < 15 and not s2.is_cycle) select i0 as i0, (n0.id, n0.kind_ids, n0.properties)::nodecomposite as n0, (n1.id, n1.kind_ids, n1.properties)::nodecomposite as n1 from unnest(array [@__strlit0::text, @__strlit1::text]::text[]) as i0, s2 join lateral (select n1.id, n1.kind_ids, n1.properties from node n1 where n1.id = s2.root_id offset 0) n1 on true join lateral (select n0.id, n0.kind_ids, n0.properties from node n0 where n0.id = s2.next_id offset 0) n0 on true) select s1.i0 as requested_root, ((s1.n1).properties -> E'objectid') as actual_root, count(*)::int8 as routes from s1 group by s1.i0, ((s1.n1).properties -> E'objectid') order by s1.i0, actual_root;
